"""v74 stage F - paper and print collections (item 67, first group): stamps, postcards, trading cards, ephemera, maps and atlases, rare books, graded comics.
Comics and rare books reuse the item 70 builders. Countries, places, teams, people and brands are invented; all text meant to appear is in double quotes."""
import random
from famlib import P, slug
from v74_books import pool, SUR_A, SUR_B, FIRST, PLACE, ADJ, NOUN
from v74_sign import q, BRANDS, SLOGAN

def an(w): return ('an ' if w[0].lower() in 'aeiou' else 'a ') + w
COUNTRY = q(P("Republic of Marlow; Kingdom of Aldmere; Free State of Dunhaven; Grand Duchy of Ravenstein; Commonwealth of Penwick; Principality of Thornmoor; Union of the Salt Coast; Dominion of Northgate; Sultanate of Kestral; Federation of Wexland; Empire of Ironvale; Confederation of Lindmark; Republic of Saint Aldric; Kingdom of Greywater"))
STAMP_SUBJ = P("a portrait of a crowned monarch in profile; a steam locomotive crossing a bridge; a colourful tropical bird; a lighthouse on a cliff; a sailing ship in full sail; a mountain peak under a clear sky; a bouquet of wild flowers; a rowing boat in a bay; a national flag with a wreath; a vintage biplane over fields; a blacksmith at an anvil; a harvest scene with a wagon; a famous bridge at dusk; a pair of dolphins leaping; a village church with a spire; a space rocket lifting off; an old mail coach with four horses; a butterfly on a leaf; a cheetah running; a map of an island")
STAMP_FORM = P("a small rectangular stamp with perforated edges; a tall narrow stamp with perforations; a large commemorative stamp with a decorative frame; a round-cornered stamp with a fine border; a triangular stamp with perforated edges; a diamond-shaped stamp; a self-adhesive stamp with die-cut edges; a stamp with straight imperforate edges; a pair of se-tenant stamps; a strip of four connected stamps")
STAMP_PRINT = P("engraved in deep single-colour ink with fine lines; printed in two colours with a tiny misregistration; lithographed in bright full colour; photogravure with a soft grainy look; embossed with a raised portrait; printed on tinted paper with a watermark; printed in black on bright coloured paper")
STAMP_MARK = P("a circular postmark in black ink; a wavy-line cancellation over the stamp; a heavy smudged postmark; a postmark with a clear date and town name; no cancellation, with original gum visible; a hinge mark on the back; a corner crease; a thinned patch on the back; perfect centring and no marks")
STAMP_PRES = P("mounted on a black album page with a transparent strip; lying in a stock book with rows of others; in a plastic-pocketed sheet; laid on a magnifier stand beside tongs; stuck on an envelope with a faded address; arranged on a table in a neat grid; in a glassine envelope; a whole sheet with perforated margins; pasted into a child's old album")
STAMP_VALUE = q(["1c", "2d", "5c", "10 pence", "25 cents", "1 shilling", "50 centimes", "3 francs", "1/2d", "20 pfennig", "6 kroner", "1 lira", "2 pesos", "75 pence"])
CARD_SET = P("a set of small colourful cards of fantasy heroes; a series of sports players in action poses; a series of vintage cars; a series of birds with painted portraits; a series of famous aircraft; a series of steam engines; a series of dinosaurs; a series of ocean creatures; a series of imaginary monsters; a series of cooks and their recipes; a series of castles; a series of explorers; a series of wildflowers; a series of warships; a series of space missions")
CARD_NAME = q(pool(81, 300, lambda r: '%s %s%s' % (r.choice(FIRST), r.choice(SUR_A), r.choice(SUR_B))))
CARD_ERA = P("a tobacco-style card from the 1900s on thin card; a 1930s cigarette-style card with a coloured picture; a 1950s card with a simple colour illustration and a blank back; a 1960s card with a sticker back; a 1970s card with a photograph and a facts box; a 1980s card with a bold border and a hologram sticker; a 1990s card with a foil effect and a stats panel; a 2000s card with a clean glossy finish; a modern card with a textured foil and a serial number")
CARD_COND = P("gem mint with razor-sharp corners; lightly rounded at the corners; off-centre with an uneven border; creased across the middle; bent at one corner; marked by a gummy stain on the back; pierced by a pin hole in the top; heavily played with soft edges; scribbled on across the back; trimmed slightly by a scissors cut; clean-edged with a sharp cut")
CARD_HOLD = P("in a plastic penny sleeve; in a hard top-loader; in a graded plastic slab with a printed label; in a binder page with eight others; held in a gloved hand; fanned in a row on a velvet cloth; in a shoebox with rubber bands; standing in a display stand; scattered on a bedroom floor; in a stack bound by a rubber band")
CARD_BACK = q(["CARD No. 14 OF 50", "No. 7 of 36", "SERIES TWO", "Set A, Card 22", "No. 31", "Rare Edition", "First Series", "Card 118 of 250"])
EPH = {
 'ticket': P("a small rectangular cardboard train ticket with a punched hole; a theatre ticket with a torn stub; a cinema ticket in faded pink; a bus ticket on thin paper; a fairground ride ticket; a football match ticket; a ferry boat ticket with a printed route; a museum entrance ticket; a concert ticket with a bold design; a raffle ticket strip"),
 'matchbox': P("a matchbox with a bright printed label; a book of matches with an advertisement; a large wooden matchbox from a hotel; a box of safety matches with a picture of a ship; a matchbox with a hand-drawn cartoon; a collection of matchbox labels pasted on a card"),
 'label': P("a paper label from a crate of fruit; a luggage label from a steamship line; a bright cigar box label with a portrait; a wine bottle label with a crest; a hotel luggage sticker; an old jam jar label; a tea chest stencil; a canning label with a picture of the vegetable"),
 'handbill': P("a theatrical playbill in bold type; a circus poster with a performing horse; a political leaflet in two colours; a wartime public notice; a concert handbill with ornate type; a fair day poster printed from woodblocks; a medicine show advertisement; a village sale notice"),
 'paperwork': P("a ration book with stamps; a school report card; a handwritten receipt; a pay packet; a certificate with a seal; a pawn ticket; a railway timetable; a menu from a ship's dining room; a wedding invitation; an old postcard order form"),
 'tin_lid': P("a tin lid with a printed picture; a bottle cap collection; a pile of metal badges; a pin-back button; a sew-on patch; a tobacco silk with a printed flag"),
}
EPH_COND = P("crisp and clean; creased in four; yellowed with age; torn along one edge; stained with a ring; faded to pale colours; folded and re-folded until it split at the creases; pierced by a pin; brittle at the edges; wrinkled and water-spotted")
EPH_PRES = P("laid on a green baize table; pasted in a scrapbook; kept in a biscuit tin; pinned to a cork board; spread across a desk with a magnifier; tucked inside an old book; filed in a binder; framed behind glass; found in a drawer")
MAP_KIND = P("a folded road map; a nautical chart; a city street plan; a hand-drawn treasure map; a large antique world map; a page from an atlas; a geological survey map; a railway network map; a hand-coloured county map; a topographical map with contour lines; a tourist map with illustrations; a map of an imaginary island")
MAP_FEAT_B = P("a scale bar in miles; blue contour lines; a red dotted route; hand-lettered place names; a legend with small symbols; small illustrations of towns; tiny ships on the sea; hachured mountains")
MAP_FEAT = P("a decorative cartouche with the title; sea monsters drawn in the ocean; a compass rose with a fleur-de-lis; a border of intricate scrollwork; a ribbon banner around the title; a decorative frame of coloured lines")
MAP_NAMES = q(pool(91, 250, lambda r: r.choice(PLACE) if r.random() < 0.5 else '%s%s' % (r.choice(SUR_A), r.choice(SUR_B))))
MAP_TITLE = q(P("A New and Accurate Map of the Region; Chart of the Northern Coast; A Plan of the City and Environs; Atlas of the Known World; Map of the Island of Penhallow; Road Map of the Central Counties; A Survey of the River Valley; Ordnance Sheet 24; Tourist Map of the Harbour District; The Navigator's Chart of the Salt Coast"))
MAP_COND = P("crisp and bright; folded with worn creases; foxed with brown spots; torn along a fold; held with old tape; hand-coloured with faded watercolour; stained with tea; backed with linen; rolled and curled at the edges; mounted on card; marked with pencil routes")
MAP_PRES = P("spread across a wooden table with brass weights at the corners; pinned to a wall; open in an atlas; framed behind glass; rolled in a leather tube; unfolded on a car bonnet; tucked into a coat pocket; hung from a rail")
POST_VIEW = P("a seaside promenade with bathing huts; a main street of shops; a lighthouse on a rock; a mountain lake; a harbour with fishing boats; a grand hotel; a village green with a duck pond; a cathedral square; a pier with a pavilion; a market day crowd; a steam railway station; a winding river bridge")
POST_TYPE = P("an early divided-back postcard with a hand-coloured picture; a linen-textured postcard of the 1940s; a glossy chrome postcard of the 1960s; a real-photo postcard on photographic paper; a comic seaside postcard with a bold cartoon; a large letter-style greeting postcard; an embossed postcard with a gold border; a modern full-colour postcard")
POST_CAPTION = q(P("Greetings from the Coast; Wish You Were Here; A Present from the Lakes; Souvenir of the Harbour; Greetings from Old Harrow; Best Wishes from the Seaside; View of the Market Square; Holiday Greetings"))
POST_MSG = q(P("Weather lovely, food terrible, back Friday; Having a wonderful time, see you soon; The hotel is not what the brochure promised; Wish you were here; Walked to the lighthouse today; Rained all week, the children are restless; Love to all at home; Arrived safely, the train was late"))
POST_COND = P("clean and crisp; bent at one corner; marked with a stamp and a postmark on the back; stained by damp along one edge; yellowed with age; marked with an album mark on the back; creased across the middle; rubbed at the corners; marked with a spot of glue on the back; scribbled over with a message across the picture")
RB_KIND = P("a first edition in original cloth; an illuminated manuscript on vellum; a large folio with copper engravings; a medieval bound volume with brass clasps; a signed copy with a dedication; a miniature book the size of a thumb; a book of hand-coloured plates; a chained library book; a leather-bound Bible with gilt edges; a fine private press book with wide margins; a pop-up book from the nineteenth century; a scrapbook of pasted cuttings")
RB_PROV = P("a bookplate pasted inside the cover reading \"Ex Libris\" and a name; a faded ownership inscription on the title page; a dealer's pencilled price on the flyleaf; a library stamp reading \"Withdrawn\"; a rubbed gilt crest on the cover; a presentation inscription in violet ink; a pressed flower between the pages; marginal notes in several hands")
RB_COND = P("in remarkably fine condition; cracked at the hinge with a loose board; worn at the spine with chipped gilt; foxed throughout with brown spots; pierced by a wormhole running through the pages; missing a leaf; restored with new leather on the spine; water-stained along the lower edge; fragile at the paper margins; bright and tight with a crisp binding")
RB_DISPLAY = P("on a brass book cradle under a lamp; in a glass-fronted case; open on a lectern; in a fitted cloth box; resting on a velvet cushion; held open with snake weights; on a dealer's table with white cotton gloves beside it; stacked with others on a library table; in a protective slipcase")
GRADE = q(P("GRADED 9.4; GRADE 8.5; GRADE 7.0; GRADE 6.0; GRADE 9.8; GRADE 5.5; GRADE 4.0; GRADE 10"))
COMIC_GRADE_CASE = P("sealed in a clear hard plastic case with a printed label; in a clear bag with a backing board; in a graded slab with a label and a serial number; in a protective mylar sleeve; loose on a table with white gloves beside it")

def build(final=None):
    G = {}
    G['text_country'] = COUNTRY; G['text_stamp_value'] = STAMP_VALUE; G['text_card_name'] = CARD_NAME; G['text_card_back'] = CARD_BACK
    G['text_map_name'] = MAP_NAMES; G['text_map_title'] = MAP_TITLE; G['text_post_caption'] = POST_CAPTION; G['text_post_message'] = POST_MSG; G['text_grade'] = GRADE
    G['stamp_subject'] = STAMP_SUBJ; G['stamp_form'] = STAMP_FORM; G['stamp_print'] = STAMP_PRINT; G['stamp_mark'] = STAMP_MARK; G['stamp_presentation'] = STAMP_PRES
    G['stamp_look'] = ['A collectable piece, __stamp_form__ from __text_country__, showing __stamp_subject__, with the value __text_stamp_value__ in the corner and the country name above, __stamp_print__.']
    G['stamp_prompt'] = ['__stamp_look__ It carries __stamp_mark__, and it is __stamp_presentation__.']
    G['stamp_prompt_fill'] = ['A collectable piece, __stamp_form__ from "COUNTRY NAME", showing __stamp_subject__, with the value "VALUE" in the corner and the country name above, __stamp_print__. It carries __stamp_mark__, and it is __stamp_presentation__.']
    G['stamp_page_prompt'] = ['An album page of stamps, each from __text_country__ and each showing a different subject. The first shows __stamp_subject__, the second shows __stamp_subject__ and the third shows __stamp_subject__, each with a value like __text_stamp_value__. The page is __stamp_presentation__.']
    G['card_set'] = CARD_SET; G['card_era'] = CARD_ERA; G['card_condition'] = CARD_COND; G['card_holder'] = CARD_HOLD
    G['card_look'] = ['A trading card from __card_set__, __card_era__. The name on the card is __text_card_name__ and the back has __text_card_back__. The card is __card_condition__, __card_holder__.']
    G['card_prompt'] = ['__card_look__']
    G['card_prompt_fill'] = ['A trading card from __card_set__, __card_era__. The name on the card is "CARD NAME" and the back has "CARD NUMBER". The card is __card_condition__, __card_holder__.']
    G['card_binder_prompt'] = ['A binder page of nine trading cards in a three by three grid, from __card_set__, the names reading __text_card_name__, __text_card_name__ and __text_card_name__ in the top row. The cards are __card_condition__. The binder is lying open on a table.']
    G['card_graded_prompt'] = ['A trading card from __card_set__, __card_era__, sealed in a graded plastic slab with the label reading __text_grade__ and __text_card_name__. The card is __card_condition__.']
    G['eph_kinds'] = list(EPH); refs = []
    for k, v in EPH.items():
        G['eph_%s' % k] = v; refs.append(k)
    G['eph_condition'] = EPH_COND; G['eph_presentation'] = EPH_PRES
    G['eph_wording'] = q(P("SPECIAL OFFER; GENUINE ARTICLE; FIRST QUALITY; WELCOME; FRESH AND PURE; FOR SALE; PAID IN FULL; BEST VALUE; THE REAL THING; COME ONE COME ALL"))
    for k in refs:
        G['eph_%s_prompt' % k] = ['Ephemera for a collection, __eph_%s__. The wording reads __eph_wording__ and __text_brand__. It is __eph_condition__, and it is __eph_presentation__.' % k]
        G['eph_%s_prompt_fill' % k] = ['Ephemera for a collection, __eph_%s__. The wording reads "TEXT" and "NAME". It is __eph_condition__, and it is __eph_presentation__.' % k]
    G['eph_prompt'] = ['__eph_%s_prompt__' % k for k in refs]; G['eph_prompt_fill'] = ['__eph_%s_prompt_fill__' % k for k in refs]
    G['eph_spread_prompt'] = ['A spread of ephemera, __eph_ticket__, __eph_matchbox__, __eph_label__ and __eph_handbill__. They are all __eph_condition__, and they are __eph_presentation__.']
    G['map_kind'] = MAP_KIND; G['map_feature'] = MAP_FEAT; G['map_feature_b'] = MAP_FEAT_B; G['map_condition'] = MAP_COND; G['map_presentation'] = MAP_PRES
    G['map_prompt'] = ['A collectable piece, __map_kind__ titled __text_map_title__, with the names __text_map_name__, __text_map_name__ and __text_map_name__ lettered on it, and __map_feature__ and __map_feature_b__. It is __map_condition__, __map_presentation__.']
    G['map_prompt_fill'] = ['A collectable piece, __map_kind__ titled "MAP TITLE", with the names "PLACE ONE", "PLACE TWO" and "PLACE THREE" lettered on it, and __map_feature__ and __map_feature_b__. It is __map_condition__, __map_presentation__.']
    G['atlas_prompt'] = ['A large atlas lying open on a table at a double-page map titled __text_map_title__, with __map_feature__ and __map_feature_b__. The pages are __map_condition__. The cover is __book_cover_colour__ __book_cover_material__ and the spine reads "ATLAS" in gold capitals.']
    G['postcard_view'] = POST_VIEW; G['postcard_type'] = POST_TYPE; G['postcard_condition'] = POST_COND
    G['postcard_prompt'] = ['A collectable piece, __postcard_type__ showing __postcard_view__, with the caption __text_post_caption__. The back is written in faded ink reading __text_post_message__. It is __postcard_condition__.']
    G['postcard_prompt_fill'] = ['A collectable piece, __postcard_type__ showing __postcard_view__, with the caption "CAPTION". The back is written in faded ink reading "MESSAGE". It is __postcard_condition__.']
    G['postcard_spread_prompt'] = ['Three postcards laid side by side. The first shows __postcard_view__ with the caption __text_post_caption__. The second shows __postcard_view__ with the caption __text_post_caption__. The third shows __postcard_view__ with the caption __text_post_caption__. They are __postcard_condition__.']
    G['rb_kind'] = RB_KIND; G['rb_provenance'] = RB_PROV; G['rb_condition'] = RB_COND; G['rb_display'] = RB_DISPLAY
    G['rb_prompt'] = ['A collectable piece, __rb_kind__, titled __book_novel_title__ by __book_author__. It has __rb_provenance__. It is __rb_condition__, __rb_display__.']
    G['rb_prompt_fill'] = ['A collectable piece, __rb_kind__, titled "BOOK TITLE" by "AUTHOR NAME". It has __rb_provenance__. It is __rb_condition__, __rb_display__.']
    G['graded_comic_prompt'] = ['A comic book titled __comic_title__ in jagged lettering above a cover of __comic_cover__. It is __comic_era__, kept in a graded case with the label reading __text_grade__ and __comic_title__.']
    G['comic_grade_case'] = COMIC_GRADE_CASE
    G['collect_paper_prompt'] = ['__stamp_prompt__', '__postcard_prompt__', '__card_prompt__', '__eph_prompt__', '__map_prompt__', '__rb_prompt__', '__graded_comic_prompt__']
    G['collect_paper_prompt_fill'] = ['__stamp_prompt_fill__', '__postcard_prompt_fill__', '__card_prompt_fill__', '__eph_prompt_fill__', '__map_prompt_fill__', '__rb_prompt_fill__']
    G['v74_paper_entry_points'] = ['collect_paper_prompt', 'collect_paper_prompt_fill', 'stamp_prompt', 'stamp_page_prompt', 'card_prompt', 'card_binder_prompt', 'card_graded_prompt', 'eph_prompt', 'eph_spread_prompt', 'map_prompt', 'atlas_prompt', 'postcard_prompt', 'postcard_spread_prompt', 'rb_prompt', 'graded_comic_prompt']
    return G
